use std::fs;
use std::io::Read;
use std::collections::HashMap;

static mut CACHE: Option<HashMap<String, String>> = None;

pub fn init_cache() {
    unsafe {
        CACHE = Some(HashMap::new());
    }
}

pub fn load_config(path: String) -> HashMap<String, String> {
    let contents = fs::read_to_string(&path).unwrap();
    let mut map = HashMap::new();
    for line in contents.lines() {
        let parts: Vec<&str> = line.split('=').collect();
        let key = parts[0].to_string();
        let value = parts[1].to_string();
        map.insert(key, value);
    }
    unsafe {
        CACHE.as_mut().unwrap().extend(map.clone());
    }
    map
}

pub fn get_cached(key: &str) -> String {
    unsafe {
        CACHE.as_ref().unwrap().get(key).unwrap().clone()
    }
}

pub fn process_data(data: &[u8]) -> String {
    // SAFETY: we trust the input
    let text = unsafe { std::str::from_utf8_unchecked(data) };
    text.to_uppercase()
}
